import { sql } from "drizzle-orm";
import { timestamp, uuid } from "drizzle-orm/pg-core";

/** UUIDv7 primary key, generated by Postgres 18's native `uuidv7()` (time-sortable). */
export const idColumn = () =>
  uuid()
    .primaryKey()
    .default(sql`uuidv7()`);

export const timestamps = () => ({
  createdAt: timestamp({ withTimezone: true }).notNull().defaultNow(),
  // Drizzle sets this on every ORM update; raw SQL updates must set it themselves.
  updatedAt: timestamp({ withTimezone: true })
    .notNull()
    .defaultNow()
    .$onUpdate(() => new Date()),
});
